/**
 * A sub-feature that provides a satellite viewer to {@link VisualGraphComponentProvider}s
 * 
 * <p>Note: this class installs actions to manipulate the satellite view.  For these to be 
 * correctly enabled, you must produce {@link VgActionContext} objects in your
 * {@link VisualGraphComponentProvider#getActionContext(MouseEvent)} method.  Specifically, 
 * the context returned must be a type of {@link VgActionContext}, with the 
 * {@link VgActionContext#shouldShowSatelliteActions()} returning true.
 * 
 * @param <V> the vertex type 
 * @param <E> the edge type
 * @param <G> the graph type
 */
//@formatter:off
public class VgSatelliteFeaturette<V, E, G> : VisualGraphFeaturette<V, E, G> where V : VisualVertex where E : VisualEdge<V> where G : VisualGraph<V, E> {
//@formatter:on

	private static readonly Icon ICON = new GIcon("icon.graph.satellite");

	private static readonly string DISPLAY_SATELLITE = "DISPLAY_SATELLITE";
	private static readonly string DOCK_SATELLITE = "DOCK_SATELLITE";
	private static readonly string DOCK_SATELLITE_POSITION = "DOCK_SATELLITE_POSITION";

	private ToggleDockingAction toggleSatelliteAction;
	private ToggleDockingAction dockSatelliteAction;
	private ToggleDockingAction upperLeftAction;
	private ToggleDockingAction upperRightAction;
	private ToggleDockingAction lowerLeftAction;
	private ToggleDockingAction lowerRightAction;

	private Tool tool;
	private VisualGraphView<object,object,object> view;
	private string owner;
	private string providerName;
	private string windowGroup;

	// a flag for us to know when we were closed because the primary graph windows was closed
	private bool closedByPrimaryProvider;

	private VgUndockedSatelliteProvider satelliteProvider;

	/* @Override */
	public void writeConfigState(SaveState saveState) {
		saveState.putBoolean(DOCK_SATELLITE, dockSatelliteAction.isSelected());
		saveState.putBoolean(DISPLAY_SATELLITE, toggleSatelliteAction.isSelected());
		saveState.putString(DOCK_SATELLITE_POSITION, view.getSatellitePosition().toString());
	}

	/* @Override */
	public void readConfigState(SaveState saveState) {

		// Note: we want to restore this value before the satellite visibility, as setting the
		// docked state will affect that state, which is what we want when the user executes the
		// action, but not when restoring saved settings.
		bool dockSatellite = saveState.getBoolean(DOCK_SATELLITE, true);
		dockSatelliteAction.setSelected(dockSatellite);
		view.setSatelliteDocked(dockSatellite);

		bool showSatellite = saveState.getBoolean(DISPLAY_SATELLITE, true);
		setSatelliteVisible(showSatellite);

		string positionString = saveState.getString(DOCK_SATELLITE_POSITION, LOWER_RIGHT.name());
		SatellitePosition position = SatellitePosition.valueOf(positionString);
		setSatellitePosition(position);
	}

	/* @Override */
	public void init(VisualGraphComponentProvider<V, E, G> provider) {

		tool = provider.getTool();
		view = provider.getView();
		owner = provider.getOwner();
		providerName = provider.getName();
		windowGroup = provider.getWindowGroup();

		view.addSatelliteListener(new SatelliteListener());

		addActions(provider);
	}

	/* @Override */
	public void providerOpened(VisualGraphComponentProvider<V, E, G> provider) {
		if (satelliteProvider != null) {
			// since the provider is not null, we know that it was previously open, closed 
			satelliteProvider.setVisible(true);
			view.setSatelliteVisible(true);
		}
	}

	/* @Override */
	public void providerClosed(VisualGraphComponentProvider<V, E, G> provider) {
		if (satelliteProvider != null) {
			closedByPrimaryProvider = true;
			satelliteProvider.closeComponent();
			closedByPrimaryProvider = false; // reset
		}
	}

	public ComponentProvider getSatelliteProvider() {
		return satelliteProvider;
	}

	private void addActions(ComponentProvider provider) {

		toggleSatelliteAction = new _Anon_ToggleDockingAction_1("Display Satellite View", owner);
		toggleSatelliteAction.setSelected(true);
		toggleSatelliteAction.setPopupMenuData(
			new MenuData(new string[] { "Display Satellite View" }));
		toggleSatelliteAction.setHelpLocation(
			new HelpLocation("VisualGraph", "Satellite_View"));

		dockSatelliteAction = new _Anon_ToggleDockingAction_2("Dock Satellite View", owner);
		dockSatelliteAction.setSelected(true);
		dockSatelliteAction.setPopupMenuData(new MenuData(new string[] { "Dock Satellite View" }));
		dockSatelliteAction.setHelpLocation(new HelpLocation("VisualGraph", "Satellite_View"));

		upperLeftAction = new SatellitePositionAction("Upper Left", UPPER_LEFT, provider);
		upperRightAction = new SatellitePositionAction("Upper Right", UPPER_RIGHT, provider);
		lowerLeftAction = new SatellitePositionAction("Lower Left", LOWER_LEFT, provider);
		lowerRightAction = new SatellitePositionAction("Lower Right", LOWER_RIGHT, provider);
		lowerRightAction.setSelected(true);

		// Note: these are not local actions, since they should appear in satellite and the main view
		tool.addAction(toggleSatelliteAction);
		tool.addAction(dockSatelliteAction);
		tool.addAction(upperLeftAction);
		tool.addAction(upperRightAction);
		tool.addAction(lowerLeftAction);
		tool.addAction(lowerRightAction);

	}

	/* @Override */
	public void remove() {
		if (satelliteProvider != null) {
			satelliteProvider.removeFromTool();
		}
	}

	public void setSatelliteVisible(bool visible) {
		toggleSatelliteAction.setSelected(visible);
		view.setSatelliteVisible(visible);
	}

	public void setSatellitePosition(SatellitePosition position) {
		deselectAllSatellitePositions();
		switch (position) {
			case LOWER_LEFT:
				lowerLeftAction.setSelected(true);
				break;
			case LOWER_RIGHT:
				lowerRightAction.setSelected(true);
				break;
			case UPPER_LEFT:
				upperLeftAction.setSelected(true);
				break;
			case UPPER_RIGHT:
				upperRightAction.setSelected(true);
				break;
		}
		view.setSatellitePosition(position);
	}

	void deselectAllSatellitePositions() {
		upperLeftAction.setSelected(false);
		upperRightAction.setSelected(false);
		lowerLeftAction.setSelected(false);
		lowerRightAction.setSelected(false);
	}

	// only remove the provider if the user had docked the satellite
	private void closeSatelliteProvider(bool remove) {
		if (satelliteProvider == null) {
			return;
		}

		if (remove) {
			satelliteProvider.removeFromTool();
			satelliteProvider = null;
		}
		else {
			satelliteProvider.closeComponent();
		}
	}

	private void showSatelliteProvider() {
		if (satelliteProvider == null) {

			JComponent component = view.getUndockedSatelliteComponent();
			satelliteProvider = new VgUndockedSatelliteProvider(tool, component,
				providerName + " Satellite", owner, windowGroup);
			satelliteProvider.setVisible(true);
		}
		else {
			satelliteProvider.toFront();
		}
	}

	private class VgUndockedSatelliteProvider : ComponentProvider {

		private JComponent satelliteComponent;

		public VgUndockedSatelliteProvider(Tool tool, JComponent component, string name,
				string owner, string windowGroup) : base(tool, name, owner)
    {

			this.satelliteComponent = component;

			satelliteComponent.setMinimumSize(new Dimension(400, 400));

			setHelpLocation(new HelpLocation("VisualGraph", "Satellite_View_Dock"));

			// this will group the satellite with the provider
			setWindowMenuGroup(windowGroup);
			setIcon(ICON);
			setDefaultWindowPosition(WindowPosition.WINDOW);

			addToTool();
		}

		/* @Override */
		public JComponent getComponent() {
			return satelliteComponent;
		}

		/* @Override */
		public ActionContext getActionContext(MouseEvent @event) {
			return new VgSatelliteContext(this);
		}

		/* @Override */
		public void componentHidden() {

			if (!dockSatelliteAction.isSelected()) {
				// this implies the user has closed the provider, but it is still undocked; 
				// sync the state of the view with this provider
				view.setSatelliteVisible(false);
			}

			if (!closedByPrimaryProvider) {
				// This is the case where the user closed this satellite provider directly.  In
				// this case, we do not want to show this provider if the main provider is later
				// re-opened.		
				satelliteProvider.removeFromTool();
				satelliteProvider = null;
			}
		}
	}

	private class SatelliteListener : GraphSatelliteListener {

		/* @Override */
		public void satelliteVisibilityChanged(bool docked, bool visible) {

			toggleSatelliteAction.setSelected(visible);
			dockSatelliteAction.setSelected(docked);

			if (docked) {
				closeSatelliteProvider(true);
				return;
			}

			if (!visible) { //  undocked and not visible
				closeSatelliteProvider(false);
			}
			else {  		// undocked and visible
				showSatelliteProvider();
			}
		}
	}

	private class SatellitePositionAction : ToggleDockingAction {

		private SatellitePosition position;
		private ComponentProvider provider;

		public SatellitePositionAction(string name, SatellitePosition posiiton,
				ComponentProvider provider) : base(name, owner)
    {
			this.position = posiiton;
			this.provider = provider;
			setPopupMenuData(new MenuData(new string[] { "Docked Satellite Position", name }));
			setHelpLocation(new HelpLocation("VisualGraph", "Satellite_Location"));
		}

		/* @Override */
		public void actionPerformed(ActionContext context) {
			deselectAllSatellitePositions();
			setSelected(true);
			view.setSatellitePosition(position);
		}

		/* @Override */
		public bool isAddToPopup(ActionContext context) {
			ComponentProvider componentProvider = context.getComponentProvider();
			if (componentProvider != provider && componentProvider != satelliteProvider) {
				// appear in satellite and the main provider
				return false;
			}

			if (context is VisualGraphActionContext vgContext) {
				return vgContext.shouldShowSatelliteActions();
			}

			return false;
		}

	}


	internal class _Anon_ToggleDockingAction_1 : ToggleDockingAction
	{
		public _Anon_ToggleDockingAction_1() : @base("Display Satellite View", owner) {}

			/* @Override */
			public void actionPerformed(ActionContext context) {
				view.setSatelliteVisible(isSelected());
			}

			/* @Override */
			public bool isAddToPopup(ActionContext context) {
				ComponentProvider componentProvider = context.getComponentProvider();
				if (componentProvider != provider && componentProvider != satelliteProvider) {
					// appear in satellite and the main provider
					return false;
				}

				if (!(context is VisualGraphActionContext vgContext)) {
					return false;
				}

				return vgContext.shouldShowSatelliteActions();
			}
		
	}


	internal class _Anon_ToggleDockingAction_2 : ToggleDockingAction
	{
		public _Anon_ToggleDockingAction_2() : @base("Dock Satellite View", owner) {}

			/* @Override */
			public void actionPerformed(ActionContext context) {
				view.setSatelliteDocked(isSelected());
			}

			/* @Override */
			public bool isAddToPopup(ActionContext context) {
				ComponentProvider componentProvider = context.getComponentProvider();
				if (componentProvider != provider && componentProvider != satelliteProvider) {
					// appear in satellite and the main provider
					return false;
				}

				if (!(context is VisualGraphActionContext vgContext)) {
					return false;
				}

				return vgContext.shouldShowSatelliteActions();
			}
		
	}

}
